  if (badge) { badge.textContent = n; badge.style.display = n ? 'grid' : 'none'; }
  const body = $('#drawerbody'); if (body) body.innerHTML = cartLinesHTML();
  const ft = $('#drawerft'); if (ft) ft.innerHTML = cartFootHTML();
