    'polaroid': (window.__SHOPIFY_VARIANTS__ && (window.__SHOPIFY_VARIANTS__['PF-CUSTOM-POLAROID'] || window.__SHOPIFY_VARIANTS__['polaroid'])) || '46630610239532'
