    var want = RM ? 0 : (my > edge ? 1 : 0.45) * near * Math.min(150, H * 0.18);
    mound += (want - mound) * (1 - Math.exp(-dt * 3.2));
    moundX += (mx - moundX) * (1 - Math.exp(-dt * 4.5));
