  const restart = () => { clearInterval(timer); if (visible) timer = setInterval(() => go(k + 1), 4000); };
  root.querySelector('[data-fp]').addEventListener('click', () => go(k - 1));
  root.querySelector('[data-fx]').addEventListener('click', () => go(k + 1));
